12	public class Animal extends Species
13	{
14	    // Fields defining a special kind of animal, they can not be changed after initialization
15	
16	    // The age at which an animal can start to breed.
17	    private final int breedingAge;
18	    // The age to which an animal can live.
19	    private final int maxAge;
20	    // The maximum number of births at once.
21	    private final int maxLitterSize;
22	    // true if the animal's sex if female
23	    private final boolean isFemale;
24	    // true if the animal hibernates during cold temperatures
25	    private final boolean hibernates;
26	    // true if the animal is active at night
27	    private final boolean isNocturnal;
28	    // the number of steps that should pass until an animal in hibernation moves
29	    private static final int STAY_STEPS = 10;
30	
31	    // Fields prone to change during the animal's life
32	
33	    // The animal's food level
34	    protected int foodLevel;
35	    // number of steps where the animal is in hibernation
36	    private int hiberSteps;
37	    // true if the animal is currently hibernating
38	    private boolean inHibernation;
39	    // The animal's age.
40	    private int age;
41	
42	    /**
43	     * Create a new animal with given specifications. An animal can be created with random age (or start at age 0) and
44	     * with a random foodLevel.
45	     *
46	     * @param field (Field) the field where the simulation takes place
47	     * @param location (Location) the Location at which the animal should appear
48	     * @param name (String) the animal's name (its species' name)
49	     * @param maximumTemperature (int) the maximum temperature the animal can survive to
50	     * @param minimumTemperature (int) the minimum temperature an animal can survive to
51	     * @param nutritionalValue (int) the animal's nutritional value
52	     * @param reproductionProbability (double) the probability that the animal reproduces at each step after a given minimum breeding age
53	     * @param maxAge (int) the animal's life expectancy
54	     * @param breedingAge (int) the age at which animal can start to reproduce
55	     * @param maxLitterSize (int) the maximum number of children the animal can have in one reproduction
56	     * @param randomAge (boolean) whether an animal should be created with a random age
57	     * @param hibernates (boolean) whether an animal is able to hibernate
58	     * @param isNocturnal (boolean) whether an animal is more active at night
59	     */
60	    public Animal(Field field, Location location, String name, int maximumTemperature, int minimumTemperature, int nutritionalValue, double reproductionProbability, int maxAge, int breedingAge, int maxLitterSize, boolean randomAge, boolean hibernates, boolean isNocturnal)
61	    {
62	        super(field, location, name, maximumTemperature, minimumTemperature, nutritionalValue, reproductionProbability);
63	
64	        this.breedingAge = breedingAge;
65	        this.maxAge = maxAge;
66	        this.maxLitterSize = maxLitterSize;
67	        this.isFemale = randomSex();
68	        this.hibernates = hibernates;
69	        this.isNocturnal = isNocturnal;
70	        // Default value is nutritionalValue to simulate the nutriment apart from the mother's milk/ other parental feeding.
71	        this.foodLevel = randomFoodLevel();
72	        inHibernation = false;
73	        hiberSteps = 0;
74	
75	        if (randomAge) {
76	            age = rand.nextInt(maxAge);
77	        } else {
78	            age = 0;
79	        }
80	    }
81	
82	    /**
83	     * Imitate an animal's step by doing the following:
84	     * 1) increment the animal's age if a year has passed.
85	     * 2) if the animal is alive, then:
86	     *      i) check if the animal should hibernate.
87	     *      ii) if the animal is in hibernation, then:
88	     *          a) if it passed STAY_STEPS steps without moving, then move and increment hunger.
89	     *          b) increment hiberSteps.
90	     *      iii) if the animal can't withstand the current temperature, then it dies.
91	     *      iv) if the animal is not in hibernation, then:
92	     *          a) if it is night and the animal is nocturnal, then move.
93	     *          b) if it is day, then all animals move and increment hunger.
94	     *
95	     * @param newSpecies (List<Species>) A list to receive newly born animals.
96	     * @param isNight (boolean) true if it is night in the simulation
97	     * @param temperature (int) the current temperature of the simulation
98	     * @param yearPassed true if a year has passed in the simulation
99	     */
100	    public void act(List<Species> newSpecies, boolean isNight, int temperature, boolean yearPassed)
101	    {
102	        // 1)
103	        if (yearPassed) {
104	            incrementAge();
105	        }
106	
107	        // 2)
108	        if(isAlive())
109	        {
110	            // i)
111	            checkHibernation(temperature);
112	            
113	            // ii)
114	            if (inHibernation)
115	            {
116	                // a)
117	                if (hiberSteps % STAY_STEPS == 0)   {
118	                    makeMove(newSpecies);
119	                    incrementHunger();
120	                }
121	                // b)
122	                incrementHiberSteps();
123	            }
124	            // iii)
125	            else if (! survivesTemperature(temperature))
126	            {
127	                setDead();
128	            }
129	            // iv)
130	            else
131	            {
132	                // a)
133	                if (isNight && isNocturnal) {
134	                    makeMove(newSpecies);
135	                }
136	                // b)
137	                else if (! isNight) {
138	                    makeMove(newSpecies);
139	                }
140	                if  (! isNight) {
141	                    incrementHunger();
142	                }
143	            }
144	        }
145	    }
146	
147	    /**
148	     * An animal's movement. It first tries to reproduce, then to eat if a plant is in one of the neighboring cells and finally to move
149	     * if an adjacent cell is available. If no adjacent cell is available, it dies of overcrowding.
150	     *
151	     * @param newSpecies (List<Species>) A list to receive newly born animals.
152	     */
153	    protected void makeMove(List<Species> newSpecies)
154	    {
155	        ArrayList<Animal> neighboringAnimalsList = getNeighboringAnimalsList();
156	
157	        if (canReproduce(neighboringAnimalsList)) {
158	            reproduce(newSpecies);
159	        }
160	
161	        // Eats if it is possible
162	        if (isNotFull()) {
163	            findFoodAndEat();
164	        }
165	
166	        // Find a free location in adjacent cells
167	        Location newLocation = getField().freeAdjacentLocation(getLocation());
168	
169	        // See if it was possible to move.
170	        if(newLocation != null) {
171	            setLocation(newLocation);
172	        }
173	        else {
174	            // Overcrowding.
175	            setDead();
176	        }
177	    }
178	
179	    /**
180	     * Returns a list of animals located in neighboring cells.
181	     *
182	     * @return (ArrayList) list of neighboring animals
183	     */
184	    protected ArrayList<Animal> getNeighboringAnimalsList()
185	    {
186	        Field field = getField();
187	        List<Location> adjacent = field.adjacentLocations(getLocation());
188	        Iterator<Location> locationIterator = adjacent.iterator();
189	
190	        ArrayList<Animal> neighboringAnimals = new ArrayList<>();
191	        while (locationIterator.hasNext())
192	        {
193	            Location where = locationIterator.next();
194	            Object species = field.getObjectAt(where);
195	
196	            if (species instanceof Animal) {
197	                Animal neighboringAnimal = (Animal) species;
198	                if (neighboringAnimal.isAlive()) {
199	                    neighboringAnimals.add(neighboringAnimal);
200	                }
201	            }
202	        }
203	        return neighboringAnimals;
204	    }
205	
206	    /**
207	     * Increase the age. This could result in the animal's death.
208	     */
209	    protected void incrementAge()
210	    {
211	        age++;
212	        if(age > maxAge) {
213	            setDead();
214	        }
215	    }
216	
217	    /**
218	     * Make this animal more hungry. This could result in the animal's death.
219	     */
220	    protected void incrementHunger()
221	    {
222	        foodLevel--;
223	        if(foodLevel <= 0) {
224	            setDead();
225	        }
226	    }
227	    
228	    /**
229	     * @return (boolean) true if the animal is not full and therefore can eat and false if it is full.
230	     */
231	    protected boolean isNotFull()
232	    {
233	        return foodLevel < getNutritionalValue()*1.5;
234	    }
235	    
236	    /**
237	     * Increment hiberSteps by 1
238	     */
239	    protected void incrementHiberSteps()
240	    {
241	        hiberSteps++;
242	    }
243	
244	    /**
245	     * Look for plants adjacent to the current location.
246	     * Only the first plant is eaten.
247	     */
248	    private void findFoodAndEat()
249	    {
250	        Field field = getField();
251	        List<Location> adjacent = field.adjacentLocations(getLocation());
252	        Iterator<Location> it = adjacent.iterator();
253	
254	        while(it.hasNext())
255	        {
256	            Location where = it.next();
257	            Object species = field.getObjectAt(where); // change in Field
258	            if(species instanceof Plant)
259	            {
260	                Plant plantSquare = (Plant) species;
261	                if(plantSquare.isAlive()) {
262	                    plantSquare.isEaten();
263	                    incrementFoodLevel(plantSquare.getNutritionalValue());
264	                    break;
265	                }
266	            }
267	        }
268	    }
269	
270	    /**
271	     * If the animal is a female, check if a male of the same species is in one of the neighboring cells. If it is the case, animal is able to reproduce
272	     *  and should go to the cel where the male is.
273	     *  Note: The task of reproducing is handled only by females so that the same reproduction can not happen twice in the same simulator step.
274	     *
275	     * @param  neighboringAnimalsList (ArrayList<Animal>) Array List of the Animal objects located in neighboring cells.
276	     * @return (boolean) if animal can reproduce.
277	     *
278	     */
279	    protected boolean canReproduce(ArrayList<Animal> neighboringAnimalsList)
280	    {
281	        // task to reproduce is handed to women only so that the same reproduction does not happen twice
282	        if (this.isFemale)
283	        {
284	            for (Animal neighbor : neighboringAnimalsList) {
285	                if (!neighbor.isFemale && neighbor.getName().equals(this.getName())) {
286	                    // The neighbor is a male of the same species
287	                    return true;
288	                }
289	            }
290	        }
291	        return false;
292	    }
293	
294	    /**
295	     * Creates the appropriate number of animals of the same species. These new animals of course share the same features as their "parent"
296	     * except the sex which is randomized,  their age and foodLevel are not randomized.
297	     *
298	     * @param  speciesInSimulation (List<Species>) List of Species objects in the simulation for the newborns to be added to it.
299	     */
300	    protected void reproduce(List<Species> speciesInSimulation)
301	    {
302	        Field field = getField();
303	        if (field != null)
304	        {
305	            List<Location> free = field.getFreeAdjacentLocations(getLocation());
306	            int births = numberOfBirths();
307	            for(int b = 0; b < births && free.size() > 0; b++) {
308	                Location loc = free.remove(0);
309	                Animal young = new Animal(field, loc, getName(), getMaximumTemperature(), getMinimumTemperature(), getNutritionalValue(), getReproductionProbability(), maxAge, breedingAge, maxLitterSize,false, hibernates, isNocturnal);
310	                speciesInSimulation.add(young);
311	            }
312	        }
313	    }
314	
315	    /**
316	     * Returns a random boolean to randomize the sex of newborns.
317	     *
318	     * @return true if female, otherwise false (male)
319	     */
320	    private boolean randomSex()
321	    {
322	        return Math.random() <= 0.5;
323	    }
324	    
325	    /**
326	     * Return a random foodLevel more than the animal's nutritional value divided by half.
327	     *
328	     * @return (int) the foodLevel.
329	     */
330	    private int randomFoodLevel()
331	    {
332	        int lowBound = getNutritionalValue()/2;
333	        return rand.nextInt(lowBound) + lowBound;
334	    }
335	
336	    /**
337	     * Generate a number representing the number of births, if it can breed.
338	     *
339	     * @return (int) The number of births (can be zero).
340	     */
341	    protected int numberOfBirths()
342	    {
343	        int births = 0;
344	        if(canGiveBirth() && rand.nextDouble() <= getReproductionProbability()) {
345	            births = rand.nextInt(maxLitterSize) + 1;
346	        }
347	        return births;
348	    }
349	
350	    /**
351	     * An animal can give birth if it has reached the minimal breeding age.
352	     */
353	    protected boolean canGiveBirth()
354	    {
355	        return age >= breedingAge;
356	    }
357	
358	    /**
359	     * Check if the animal should be in hibernation.
360	     *
361	     * Change inHibernation to true if the animal can hibernate
362	     * and the current temperature is less than or equal the
363	     * minimum temperature of the animal + 5
364	     *
365	     * @param currentTemperature (int) the current temperature of the simulation
366	     */
367	    protected void checkHibernation(int currentTemperature)
368	    {
369	        if (hibernates && currentTemperature <= getMinimumTemperature() + 5)  {
370	            inHibernation = true;
371	        }
372	        else {
373	            inHibernation = false;
374	            hiberSteps = 0;
375	        }
376	    }
377	
378	    /**
379	     * @return (int) The maximum age to which an animal can live
380	     */
381	    protected int getMaxAge ()
382	    {
383	        return maxAge;
384	    }
385	
386	    /**
387	     * @return (int) The age at which an animal can start to breed
388	     */
389	    protected int getBreedingAge ()
390	    {
391	        return breedingAge;
392	    }
393	
394	    /**
395	     * @return (int) The maximum number of births at once
396	     */
397	    protected int getMaxLitterSize ()
398	    {
399	        return maxLitterSize;
400	    }
401	
402	    /**
403	     * @return (boolean) true if the animal hibernates
404	     */
405	    protected boolean getHibernates()
406	    {
407	        return hibernates;
408	    }
409	
410	    /**
411	     * @return (boolean) true if the animal is active at night
412	     */
413	    protected boolean getIsNocturnal()
414	    {
415	        return isNocturnal;
416	    }
417	
418	    /**
419	     * Increments the animal's food level by a given number (the nutritional value of the food he just ate).
420	     * It is public because a predator's food level can be incremented another predator in the case that it attacks it.
421	     *
422	     * @param value (int) the number to increment foodLevel by.
423	     */
424	    public void incrementFoodLevel(int value) {
425	        foodLevel += value;
426	    }
427	
428	}
